"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'Engines of Hope', 'author': 'Signature original', 'genre': 'Starship Sagas', 'chapters': [{'n': 1, 'title': 'Launch', 'text': "Engineer Pip Solano ran the numbers with grease on their hands and worry in their eyes. 'the Hollow Fleet has three ships in the drift,' they said. 'If we burn hard, we can make it. If we burn hard, everyone will see us.'\n\nThey grappled a star chart etched in crystal with the cargo arm as the first raider shells crossed their bow. Engineer Pip Solano whooped as the airlock sealed. Whatever a star chart etched in crystal was, it was theirs now — and the Hollow Fleet knew it.\n\nCommander Dax Renn gave the order anyway. The engines lit, the deck hummed, and the ship leapt toward a star chart etched in crystal with Station Meridian falling behind. Some cargoes, Commander Dax Renn knew, are worth the whole sky."}, {'n': 2, 'title': 'The Chart Unfolds', 'text': "In the quiet after, Commander Dax Renn played the starlog again. The voice — old, tired, kind — said: 'Whoever finds this, Station Meridian needs you. Hurry.' Commander Dax Renn set the course and did not look back.\n\n'It's a map,' breathed Commander Dax Renn, 'and a warning.' The route it drew cut through the worst of the drift: plasma storms, minefields, and the patrol lanes of the Hollow Fleet.\n\nThey burned for the first waypoint with raiders on their tail. Commander Dax Renn flew the ship like a thrown knife, skimming a gravity well so close the hull sang. Behind them, the Hollow Fleet's vanguard broke off, unwilling to follow."}, {'n': 3, 'title': 'Storm Season', 'text': "A mine took their port array. The deck went dark, then red. Engineer Pip Solano was already moving, cable in teeth, splicing by feel. 'Talk to me,' Commander Dax Renn said, and Engineer Pip Solano talked — numbers, jokes, anything to keep the fear small.\n\nThe plasma storm hit at the second waypoint, a wall of fire across the sky. Engineer Pip Solano rerouted everything to the shields, hands flying, while Commander Dax Renn threaded the ship through gaps that opened and closed like eyes.\n\nAfterward, Commander Dax Renn looked at each face on the bridge and said it plainly: 'There's a traitor aboard. I don't know who. But a star chart etched in crystal goes to Station Meridian — with all of us, or with whoever's left.'"}, {'n': 4, 'title': "The Traitor's Price", 'text': "Engineer Pip Solano caught them at the airlock. There was no fight — only the traitor crying that the Hollow Fleet held their family. Commander Dax Renn understood, and hated understanding. Mercy, out here, was a luxury with teeth.\n\nThen a star chart etched in crystal spoke — fully, at last. Not a map but a key, and not to a place but to a shield: an ancient defense grid sleeping around Station Meridian, the only thing that could stop the Hollow Fleet's fleet.\n\nCommander Dax Renn laughed for the first time in days. 'All this way,' they said, 'and we were carrying the lock, not the treasure.' Engineer Pip Solano was already calculating the wake-up sequence."}, {'n': 5, 'title': 'The Grid Awakens', 'text': "Silence, then. The grid humming. Station Meridian safe below. Engineer Pip Solano put a hand on Commander Dax Renn's shoulder and said what everyone was thinking: 'We live.'\n\nThe flagship came on anyway, and Commander Dax Renn met it ship to ship above the burning sky. It was the Hollow Fleet themselves on the viewscreen, offering one last deal. Commander Dax Renn answered with the engines at full burn.\n\nThe duel was legend before it ended: two ships in the fire-light, neither yielding, until Commander Dax Renn did the impossible — dove through the grid's own gate, which a star chart etched in crystal held open, and watched the Hollow Fleet break against the shield they could not see."}, {'n': 6, 'title': 'Home Signal', 'text': "They landed at Station Meridian to crowds and bells. The old voice from the starlog had belonged to the grid's last keeper, dead a hundred years; a star chart etched in crystal was their final message. Commander Dax Renn laid it in the memorial with honors.\n\nAnd when the next distress call came — as it always does, out in the drift — the engines were already warm. There are always more skies. There is always Station Meridian, somewhere, needing its heroes.\n\nEngineer Pip Solano was offered an admiralty and laughed in the committee's face. 'I have a ship,' they said. It was the highest compliment the crew had ever heard."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

